"""Load campaign result tables and render Markdown outputs.

Standardizes loading for simulation outputs (trials.csv, frontier_cells.csv,
frontier_groups.csv, and calibration.json) by handling generated header notices
consistently, and formats pandas DataFrames as Markdown tables without extra dependencies.
"""

from __future__ import annotations

import json
from pathlib import Path

import pandas as pd


def read_table(path: Path) -> pd.DataFrame:
    """Reads a CSV file generated by HerdSim, skipping the top provenance notice."""
    return pd.read_csv(path, skiprows=1, low_memory=False)


def read_trials(folder: Path) -> pd.DataFrame:
    """Loads trials.csv from a campaign results directory."""
    return read_table(folder / "trials.csv")


def read_cells(folder: Path) -> pd.DataFrame:
    """Loads frontier_cells.csv from a campaign results directory."""
    return read_table(folder / "frontier_cells.csv")


def read_groups(folder: Path) -> pd.DataFrame:
    """Loads frontier_groups.csv from a campaign results directory."""
    return read_table(folder / "frontier_groups.csv")


def flock_radii(folder: Path) -> dict[str, dict[str, float]]:
    """Loads calibrated flock radii R_f per method from calibration.json."""
    return json.loads((folder / "calibration.json").read_text())["flock_radius"]


def markdown(frame: pd.DataFrame, index: bool = False) -> str:
    """Renders a pandas DataFrame as a Markdown table string."""
    if frame.empty:
        return "(no rows)"
    frame = frame.reset_index() if index else frame
    columns = [c for c in frame.columns]
    lines = ["| " + " | ".join(columns) + " |", "|" + "|".join("---" for _ in columns) + "|"]
    for row in frame.itertuples(index=False):
        cells = ("" if isinstance(v, float) and pd.isna(v) else str(v) for v in row)
        lines.append("| " + " | ".join(cells) + " |")
    return "\n".join(lines)
